-- V1__create_repository_schema.sql
-- Tech Debt Assistant (TDA)
-- PostgreSQL schema for repository metadata, immutable revisions, and revision files.
--
-- UUID values are generated by the application. This migration intentionally does not
-- require pgcrypto or uuid-ossp extensions.

CREATE TABLE repository (
    id              UUID PRIMARY KEY,
    clone_url       TEXT NOT NULL,
    display_name    VARCHAR(255) NOT NULL,
    default_branch  VARCHAR(255),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT uq_repository_clone_url UNIQUE (clone_url),
    CONSTRAINT ck_repository_clone_url_https
		CHECK (
			clone_url ~* '^https://[^/[:space:]]+(/[^[:space:]]*)?$'
			AND length(clone_url) <= 2048
		),
    CONSTRAINT ck_repository_display_name_not_blank
        CHECK (length(btrim(display_name)) > 0),
    CONSTRAINT ck_repository_default_branch_not_blank
        CHECK (default_branch IS NULL OR length(btrim(default_branch)) > 0)
);

COMMENT ON TABLE repository IS
    'A registered public Git repository. URL allowlisting and SSRF protection must also be enforced by the application.';
COMMENT ON COLUMN repository.clone_url IS
    'Canonical HTTPS clone URL; the application must validate hosts, redirects, DNS resolution, and private-network targets.';
COMMENT ON COLUMN repository.default_branch IS
    'Informational branch name only; analyses must be pinned to a commit hash.';

CREATE TABLE repository_revision (
    id              UUID PRIMARY KEY,
    repository_id   UUID NOT NULL,
    commit_hash     VARCHAR(64) NOT NULL,
    branch_name     VARCHAR(255),
    indexed_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_repository_revision_repository
        FOREIGN KEY (repository_id)
        REFERENCES repository (id)
        ON DELETE CASCADE,
    CONSTRAINT uq_repository_revision_commit
        UNIQUE (repository_id, commit_hash),
    -- Supports a composite FK from repository_file, ensuring a file's revision
    -- belongs to the same repository as the revision metadata.
    CONSTRAINT uq_repository_revision_repository_id
        UNIQUE (repository_id, id),
    CONSTRAINT ck_repository_revision_commit_hash
        CHECK (commit_hash ~ '^([0-9a-f]{40}|[0-9a-f]{64})$')
);

COMMENT ON TABLE repository_revision IS
    'An immutable Git commit selected for indexing or analysis.';
COMMENT ON COLUMN repository_revision.commit_hash IS
    'Full lowercase Git object ID (SHA-1, 40 hex characters, or SHA-256, 64 hex characters).';

CREATE INDEX ix_repository_revision_repository_created
    ON repository_revision (repository_id, created_at DESC);

CREATE TABLE repository_file (
    id              UUID PRIMARY KEY,
    repository_id   UUID NOT NULL,
    revision_id     UUID NOT NULL,
    path            TEXT NOT NULL,
    content_hash    VARCHAR(64) NOT NULL,
    language        VARCHAR(100),
    size_bytes      BIGINT NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_repository_file_revision
        FOREIGN KEY (repository_id, revision_id)
        REFERENCES repository_revision (repository_id, id)
        ON DELETE CASCADE,
    CONSTRAINT uq_repository_file_revision_path
        UNIQUE (revision_id, path),
    -- Allows later tables to reference a file while enforcing revision consistency.
    CONSTRAINT uq_repository_file_revision_file
        UNIQUE (revision_id, id),
    CONSTRAINT ck_repository_file_path_not_blank
        CHECK (length(btrim(path)) > 0),
    CONSTRAINT ck_repository_file_path_relative
        CHECK (
			path !~ '^/'
			AND path !~ '^[A-Za-z]:'
			AND path !~ E'(^|/)\\.\\.(/|$)'
			AND path !~ E'(^|\\\\)\\.\\.(\\\\|$)'
			AND path !~ E'\\\\'
		),
    CONSTRAINT ck_repository_file_content_hash
        CHECK (content_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_repository_file_size_nonnegative
        CHECK (size_bytes >= 0),
    CONSTRAINT ck_repository_file_language_not_blank
        CHECK (language IS NULL OR length(btrim(language)) > 0)
);

COMMENT ON TABLE repository_file IS
    'A file snapshot within one exact repository revision. Paths are repository-relative.';
COMMENT ON COLUMN repository_file.content_hash IS
    'SHA-256 hash of the file content, used to detect unchanged files across revisions.';

CREATE INDEX ix_repository_file_repository_revision
    ON repository_file (repository_id, revision_id);

CREATE INDEX ix_repository_file_content_hash
    ON repository_file (content_hash);

CREATE INDEX ix_repository_file_language
    ON repository_file (language)
    WHERE language IS NOT NULL;
